+#[test]
+fn direct_symbol_priority_applies_before_the_memory_cap() {
+    let code = (0..6)
+        .map(|i| format!("def stage_{i}():\n    return {i}\n\n"))
+        .collect::<String>();
+    let f = Fixture::new(&[("pipeline.py", &code)]);
+    let notes: Vec<Value> = (0..6)
+        .map(|i| {
+            f.note(
+                [
+                    "Quokka ledger",
+                    "Wombat archive",
+                    "Orchid protocol",
+                    "Cedar sampling",
+                    "Peer lifetime",
+                    "Violet ordering",
+                ][i],
+                "Preserve the original fiscal records.",
+                json!([{"path":"pipeline.py","qualified_name":format!("stage_{i}")}]),
+            )
+        })
+        .collect();
+    for (i, note) in notes.iter().enumerate() {
+        let packet = f.context(
